def minimum_shelf_height(books, shelf_width):
 dp=[0]+[10**9]*len(books)
 for end in range(1,len(books)+1):
  width=height=0
  for start in range(end-1,-1,-1):
   width+=books[start][0]
   if width>shelf_width:break
   height=max(height,books[start][1]);dp[end]=min(dp[end],dp[start]+height)
 return dp[-1]

